package com.example.melonstools.data;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.saveddata.SavedData;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Persisted, server-authoritative payroll batches. Payment is intentionally disabled until LC refund is verified. */
public class PayrollSavedData extends SavedData {
 public static final String DATA_NAME="melon_payroll"; public static final int SCHEMA_VERSION=1;
 public static final String DRAFT="draft",SUBMITTED="submitted",APPROVED="approved",PAYING="paying",PAID="paid",CANCELLED="cancelled",FAILED="failed";
 public static final String LINE_PENDING="pending",LINE_PAID="paid",LINE_FAILED="failed",LINE_CANCELLED="cancelled";
 private final List<Batch> batches=new ArrayList<>(); private int sequence;
 public static PayrollSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(PayrollSavedData::load,PayrollSavedData::new,DATA_NAME);}
 public static PayrollSavedData load(CompoundTag t){PayrollSavedData d=new PayrollSavedData();d.sequence=t.getInt("Sequence");ListTag a=t.getList("Batches",Tag.TAG_COMPOUND);for(int i=0;i<a.size();i++)d.batches.add(Batch.load(a.getCompound(i)));return d;}
 public CompoundTag save(CompoundTag t){t.putInt("SchemaVersion",SCHEMA_VERSION);t.putInt("Sequence",sequence);ListTag a=new ListTag();for(Batch b:batches)a.add(b.save());t.put("Batches",a);return t;}
 public List<Batch> batches(){return Collections.unmodifiableList(batches);} public String nextBatchId(){return "payroll-"+(++sequence);} public void add(Batch b){batches.add(b);setDirty();}
 public Batch find(String id){if(id==null)return null;for(Batch b:batches)if(id.equals(b.batchId))return b;return null;}
 public String nextLineId(Batch b){return b.batchId+"-line-"+(b.lines.size()+1);}
 private static String clean(String v,int max){if(v==null)return "";v=v.trim();return v.length()>max?v.substring(0,max):v;}
  private static boolean canManage(net.minecraft.server.level.ServerPlayer p){return p!=null&&(p.hasPermissions(2)||com.example.melonstools.department.DepartmentPolicy.isFacilityDirector(p));}
  private static boolean canEdit(net.minecraft.server.level.ServerPlayer p,Batch b){return p!=null&&b!=null&&(canManage(p)||b.creatorUuid.equals(p.getUUID().toString()));}
  public Batch createBatch(net.minecraft.server.level.ServerPlayer p,String period,String note){period=clean(period,48);if(!canManage(p)||period.isEmpty())return null;Batch b=new Batch();b.batchId=nextBatchId();b.creatorUuid=p.getUUID().toString();b.creatorName=p.getGameProfile().getName();b.periodLabel=period;b.note=clean(note,300);b.createdAt=System.currentTimeMillis();b.version=1;add(b);return b;}
  public boolean addLine(net.minecraft.server.level.ServerPlayer actor,String batchId,String targetName,String targetUuid,long amount,String reason){Batch b=find(batchId);if(b==null||!DRAFT.equals(b.status)||!canEdit(actor,b)||amount<=0||amount>100000000L)return false;String tu=clean(targetUuid,64),tn=clean(targetName,64);if(tu.isEmpty()){try{java.util.UUID u=com.example.melonstools.idcard.LCIntegration.resolvePlayerUUID(actor.server,tn);if(u!=null)tu=u.toString();}catch(Throwable ignored){}}if(tu.isEmpty()||tn.isEmpty())return false;for(Line old:b.lines)if(tu.equals(old.targetUuid)&&LINE_PENDING.equals(old.status))return false;Line l=new Line();l.lineId=nextLineId(b);l.batchId=batchId;l.targetUuid=tu;l.targetName=tn;l.amount=amount;l.reason=clean(reason,200);b.lines.add(l);b.total+=amount;b.version++;setDirty();return true;}
  public boolean removeLine(net.minecraft.server.level.ServerPlayer p,String batchId,String lineId){Batch b=find(batchId);if(b==null||!DRAFT.equals(b.status)||!canEdit(p,b))return false;for(int i=0;i<b.lines.size();i++)if(lineId.equals(b.lines.get(i).lineId)){b.total-=b.lines.get(i).amount;b.lines.remove(i);b.version++;setDirty();return true;}return false;}
  public boolean submit(net.minecraft.server.level.ServerPlayer p,String id,long expected){Batch b=find(id);if(b==null||!DRAFT.equals(b.status)||b.lines.isEmpty()||b.version!=expected||!b.creatorUuid.equals(p.getUUID().toString()))return false;b.status=SUBMITTED;b.submittedAt=System.currentTimeMillis();b.version++;setDirty();return true;}
  public boolean approve(net.minecraft.server.level.ServerPlayer p,String id,long expected){Batch b=find(id);if(b==null||!SUBMITTED.equals(b.status)||b.version!=expected||b.creatorUuid.equals(p.getUUID().toString())||(!com.example.melonstools.department.DepartmentPolicy.isFacilityDirector(p)&&!p.hasPermissions(2)))return false;b.status=APPROVED;b.approvedAt=System.currentTimeMillis();b.approvedTotal=b.total;b.version++;setDirty();return true;}
  public boolean cancel(net.minecraft.server.level.ServerPlayer p,String id,long expected){Batch b=find(id);if(b==null||b.version!=expected||PAID.equals(b.status)||CANCELLED.equals(b.status)||(!b.creatorUuid.equals(p.getUUID().toString())&&!com.example.melonstools.department.DepartmentPolicy.isFacilityDirector(p)&&!p.hasPermissions(2)))return false;b.status=CANCELLED;b.cancelledAt=System.currentTimeMillis();b.version++;for(Line l:b.lines)l.status=LINE_CANCELLED;setDirty();return true;}
  public boolean retry(net.minecraft.server.level.ServerPlayer p,String id,long expected){Batch b=find(id);if(b==null||!FAILED.equals(b.status)||b.version!=expected||(!b.creatorUuid.equals(p.getUUID().toString())&&!com.example.melonstools.department.DepartmentPolicy.isFacilityDirector(p)&&!p.hasPermissions(2)))return false;b.status=SUBMITTED;b.failureReason="";b.version++;for(Line l:b.lines)if(LINE_FAILED.equals(l.status)){l.status=LINE_PENDING;l.failureReason="";}setDirty();return true;}
  public JsonObject toJsonFor(){JsonObject r=new JsonObject(),s=new JsonObject();long paid=0;int pending=0,submitted=0,approved=0;JsonArray bs=new JsonArray(),ls=new JsonArray();for(Batch b:batches){if(DRAFT.equals(b.status))pending++;if(SUBMITTED.equals(b.status))submitted++;if(APPROVED.equals(b.status))approved++;if(PAID.equals(b.status))paid+=b.total;JsonObject x=b.json();bs.add(x);for(Line l:b.lines){JsonObject y=l.json();y.addProperty("batchId",b.batchId);ls.add(y);}}s.addProperty("balanceText","0");s.addProperty("pendingCount",pending);s.addProperty("submittedCount",submitted);s.addProperty("approvedCount",approved);s.addProperty("paidTotal",paid);r.add("summary",s);r.add("batches",bs);r.add("lines",ls);r.addProperty("paymentEnabled",false);r.addProperty("paymentBlockedReason","LC退款/事务API未验证，付款安全拒绝");return r;}
 public static class Batch{public String batchId="",status=DRAFT,creatorUuid="",creatorName="",periodLabel="",note="",failureReason="",idempotencyKey="";public long createdAt,submittedAt,approvedAt,paidAt,cancelledAt,total,approvedTotal,version;public final List<Line> lines=new ArrayList<>();
  CompoundTag save(){CompoundTag t=new CompoundTag();t.putString("BatchId",batchId);t.putString("Status",status);t.putString("CreatorUuid",creatorUuid);t.putString("CreatorName",creatorName);t.putString("PeriodLabel",periodLabel);t.putString("Note",note);t.putString("FailureReason",failureReason);t.putString("IdempotencyKey",idempotencyKey);t.putLong("CreatedAt",createdAt);t.putLong("SubmittedAt",submittedAt);t.putLong("ApprovedAt",approvedAt);t.putLong("PaidAt",paidAt);t.putLong("CancelledAt",cancelledAt);t.putLong("Total",total);t.putLong("ApprovedTotal",approvedTotal);t.putLong("Version",version);ListTag a=new ListTag();for(Line l:lines)a.add(l.save());t.put("Lines",a);return t;}
  static Batch load(CompoundTag t){Batch b=new Batch();b.batchId=t.getString("BatchId");b.status=t.getString("Status");b.creatorUuid=t.getString("CreatorUuid");b.creatorName=t.getString("CreatorName");b.periodLabel=t.getString("PeriodLabel");b.note=t.getString("Note");b.failureReason=t.getString("FailureReason");b.idempotencyKey=t.getString("IdempotencyKey");b.createdAt=t.getLong("CreatedAt");b.submittedAt=t.getLong("SubmittedAt");b.approvedAt=t.getLong("ApprovedAt");b.paidAt=t.getLong("PaidAt");b.cancelledAt=t.getLong("CancelledAt");b.total=t.getLong("Total");b.approvedTotal=t.getLong("ApprovedTotal");b.version=t.getLong("Version");ListTag a=t.getList("Lines",Tag.TAG_COMPOUND);for(int i=0;i<a.size();i++)b.lines.add(Line.load(a.getCompound(i)));return b;}
  JsonObject json(){JsonObject o=new JsonObject();o.addProperty("batchId",batchId);o.addProperty("status",status);o.addProperty("creatorName",creatorName);o.addProperty("periodLabel",periodLabel);o.addProperty("note",note);o.addProperty("failureReason",failureReason);o.addProperty("total",total);o.addProperty("version",version);return o;}}
 public static class Line{public String lineId="",batchId="",targetUuid="",targetName="",department="",position="",reason="",status=LINE_PENDING,failureReason="";public int level;public long amount,paidAt;CompoundTag save(){CompoundTag t=new CompoundTag();t.putString("LineId",lineId);t.putString("BatchId",batchId);t.putString("TargetUuid",targetUuid);t.putString("TargetName",targetName);t.putString("Department",department);t.putString("Position",position);t.putInt("Level",level);t.putLong("Amount",amount);t.putString("Reason",reason);t.putString("Status",status);t.putString("FailureReason",failureReason);t.putLong("PaidAt",paidAt);return t;}static Line load(CompoundTag t){Line l=new Line();l.lineId=t.getString("LineId");l.batchId=t.getString("BatchId");l.targetUuid=t.getString("TargetUuid");l.targetName=t.getString("TargetName");l.department=t.getString("Department");l.position=t.getString("Position");l.level=t.getInt("Level");l.amount=t.getLong("Amount");l.reason=t.getString("Reason");l.status=t.getString("Status");l.failureReason=t.getString("FailureReason");l.paidAt=t.getLong("PaidAt");return l;}JsonObject json(){JsonObject o=new JsonObject();o.addProperty("lineId",lineId);o.addProperty("targetName",targetName);o.addProperty("department",department);o.addProperty("position",position);o.addProperty("level",level);o.addProperty("amount",amount);o.addProperty("reason",reason);o.addProperty("status",status);o.addProperty("failureReason",failureReason);return o;}}
}
